from nlib import *
S=[]
def T(id,title,sc,sm,b,d,e,f,dy,made,sec,kn=("cell_types",),par=(),rel=(),mol=None,cert="C1",oq=None):
    S.append(N(id,title,"tissue","micro",sc,sm,b,d,e,f,dy,par=par,made=made,refs=[("ANP",sec)],kn=kn,rel=rel,mol=mol,cert=cert,oq=oq))
T("epithelial_tissue","Epithelial tissue",1e-4,"Sheets of tightly joined cells that line surfaces and form glands.","Epithelia cover your skin and line your gut, lungs and vessels. They are barriers that also absorb and secrete.","Classified by cell layers (simple vs stratified) and shapes (squamous, cuboidal, columnar). They sit on a basement membrane and have no blood vessels.","Polarized cells joined by tight junctions, adherens junctions, desmosomes; apical and basolateral domains with distinct transporters; high turnover and stem-cell renewal.",[("Thickness","≈ 10-100 µm"),("Types","≈ 8 common"),("Blood vessels","none")],"Epithelial cells are the origin of about 85-90% of cancers (carcinomas).",["keratinocyte","enterocyte"],"4.2")
T("connective_tissue_loose","Loose connective tissue",1e-4,"A flexible packing tissue with fibers and cells in a gel-like matrix.","It fills spaces between organs and holds structures in place.","Fibroblasts make collagen and elastin fibers in a ground substance of hydrated proteoglycans.","Areolar tissue is rich in fibroblasts, mast cells and macrophages; extracellular matrix composition determines mechanics.",[("Main cell","fibroblast"),("Main fiber","collagen")],"Collagen is the most abundant protein in the human body.",["fibroblast"],"4.3",mol=["aa_gly","aa_pro"])
T("dense_connective_tissue","Dense connective tissue",1e-3,"Tough, fiber-packed tissue forming tendons, ligaments and capsules.","Very strong and rope-like tissue that links muscle to bone and bone to bone.","Dense regular tissue has parallel collagen fibers (tendon); dense irregular has woven fibers (dermis).","Type I collagen fibrils bundled into fascicles; sparse fibroblasts (tenocytes); poor blood supply slows healing.",[("Tensile strength","≈ 50-100 MPa (tendon)"),("Collagen content","≈ 70-80% dry mass")],"Tendons can store and return a significant part of the energy of a running stride.",["fibroblast"],"4.3")
T("adipose_tissue","Adipose tissue",1e-3,"Fat tissue that stores energy and insulates.","Fat cells store extra energy as oil droplets and also cushion organs.","White fat stores energy, brown fat makes heat, and fat also releases hormones such as leptin.","Adipocytes ≈ 70-120 µm; adipokines (leptin, adiponectin); beige adipocytes can express UCP1; typical body fat ≈ 15-30% in adults.",[("Fat share of body","≈ 15-30%"),("Energy density","≈ 37 kJ/g")],"Brown fat, once thought only in infants, is also found in adults.",["adipocyte"],"4.3",kn=("metabolism_overview",))
T("cartilage_tissue","Cartilage",1e-3,"Firm, flexible tissue found in joints, nose, ears and airways.","Cartilage is smoother and bendier than bone, and cushions joints.","Chondrocytes in lacunae make a matrix rich in collagen II and proteoglycans, without blood vessels.","Hyaline, elastic and fibrocartilage types; avascular so repair is slow; aggrecan holds water giving compressive stiffness.",[("Water content","≈ 70-80%"),("Blood vessels","none")],"Your nose and ears are mostly cartilage and keep growing slightly through life.",["chondrocyte"],"4.3")
T("bone_tissue","Bone tissue",1e-3,"Mineralized connective tissue that is hard yet living.","Bone is a living material, mostly collagen strengthened with calcium phosphate crystals.","Cells within bone sense strain and direct remodeling; blood vessels run through it.","≈ 65% mineral (hydroxyapatite), ≈ 25% organic (mostly collagen I), ≈ 10% water by weight; osteon structure; turnover ≈ 10% of skeleton yearly.",[("Mineral","≈ 65% by mass"),("Turnover","≈ 10%/yr")],"Your skeleton is gradually replaced; most adult bone is renewed over ~10 years.",["osteocyte","osteoblast"],"6.3",kn=("musculoskeletal",),proc=()) if False else None
T("bone_tissue","Bone tissue",1e-3,"Mineralized connective tissue that is hard yet living.","Bone is a living material, mostly collagen strengthened with calcium phosphate crystals.","Cells within bone sense strain and direct remodeling, and blood vessels run through it.","About 65% mineral (hydroxyapatite), ≈ 25% organic (mostly collagen I) and ≈ 10% water by weight; osteon structure; turnover of ≈ 10% of the skeleton per year.",[("Mineral","≈ 65% by mass"),("Turnover","≈ 10%/yr")],"Most of your adult skeleton is replaced over about a decade.",["osteocyte","osteoblast"],"6.3",kn=("musculoskeletal",),mol=["phosphate"])
T("blood_tissue","Blood tissue",1e-5,"A fluid connective tissue: cells suspended in plasma.","Blood is a tissue with floating cells in liquid.","Cells include red cells, white cells and platelets; plasma carries proteins and solutes.","Hematopoiesis from HSCs; erythrocytes ≈ 4.5-5.5×10^12/L, leukocytes ≈ 4-11×10^9/L, platelets ≈ 150-400×10^9/L.",[("Red cells","≈ 5×10^12/L"),("White cells","≈ 7×10^9/L"),("Platelets","≈ 2.5×10^11/L")],"Red blood cells outnumber white cells about 700 to 1.",["red_blood_cell","neutrophil","lymphocyte_t","lymphocyte_b","macrophage","platelet"],"18.1",kn=("blood_circulation",),mol=["heme_b"])
T("skeletal_muscle_tissue","Skeletal muscle tissue",1e-2,"Striped muscle tissue under voluntary control.","Muscles are bundles of long fibers that shorten when told to.","Each muscle fiber is a giant multinucleated cell packed with striped contractile units.","Fibers bundled into fascicles with endomysium, perimysium, epimysium; satellite cells repair; motor-unit organization.",[("Fiber length","≈ up to cm"),("Fiber diameter","≈ 50-100 µm")],"A muscle fiber can have hundreds of nuclei in one cell.",["skeletal_muscle_fiber"],"10.2",kn=("muscle_contraction",))
T("cardiac_muscle_tissue","Cardiac muscle tissue",1e-4,"Striated, involuntary muscle of the heart with branching cells.","The heart muscle never rests and cannot tire.","Cells are joined end to end at intercalated discs, so electrical signals spread.","Gap junctions (connexin 43) enable syncytium-like conduction; desmosomes bear force; ≈ 25-35% of volume is mitochondria.",[("Cell length","≈ 100 µm"),("Mitochondria","≈ 30% of volume")],"Heart muscle cells turn over very slowly, around 1% per year in young adults.",["cardiomyocyte"],"10.7",kn=("muscle_contraction",),mol=["atp"])
T("smooth_muscle_tissue","Smooth muscle tissue",1e-4,"Unstriped involuntary muscle in vessel walls and organs.","Smooth muscle squeezes slowly without conscious control in the gut, vessels and bladder.","Spindle-shaped cells with one nucleus; contractions are slow and sustained.","Contraction via Ca2+-calmodulin-MLCK phosphorylation of myosin light chain; latch state conserves ATP.",[("Cell length","≈ 30-200 µm"),("Nuclei per cell","1")],"Uterine smooth muscle cells grow in length about tenfold during pregnancy.",["smooth_muscle_cell"],"10.8",kn=("muscle_contraction",))
T("nervous_tissue","Nervous tissue",1e-4,"Tissue of neurons and supporting glial cells.","Neurons send signals; glial cells feed, insulate and protect them.","Gray matter is cell-body rich and white matter holds myelinated fibers.","Neurons, astrocytes, oligodendrocytes, microglia (CNS); Schwann cells (PNS); glia:neuron ratio is ≈ 1:1 overall in the human brain.",[("Glia:neuron","≈ 1:1"),("Brain water","≈ 75-80%")],"The old '10 glia for each neuron' idea has been revised to roughly one to one.",["neuron","astrocyte"],"4.5",kn=("brain_organization",))
save("body_tissues",S)
S2=[]
for i,t,sm,b,d,e,f,dy,sec in [
("simple_squamous_epithelium","Simple squamous epithelium","A single layer of flat cells for fast exchange.","One thin layer of flat cells lines air sacs and blood vessels, letting gases pass easily.","Found in alveoli (type I cells), capillary endothelium and mesothelium.","Thickness ≈ 0.1-0.5 µm in the alveolar wall; allows passive diffusion.",[("Thickness","≈ 0.2-2 µm")],"The alveolar lining is thinner than a soap bubble wall in places on a scale relative to the lung.","4.2"),
("simple_columnar_epithelium","Simple columnar epithelium","A single layer of tall cells for absorption and secretion.","Tall cells line your intestines and absorb nutrients.","Often has microvilli and goblet cells that secrete mucus.","Tight junctions between enterocytes separate lumen from internal milieu; brush border enzymes.",[("Cell height","≈ 20-30 µm")],"Goblet cells produce about a liter of mucus a day in the gut.","4.2"),
("stratified_squamous_epithelium","Stratified squamous epithelium","Many layers of cells that resist wear, like skin.","Layered flat cells tough enough for the skin, mouth and esophagus.","Keratinized in skin, non-keratinized in mouth and esophagus.","Basal stem cells renew the layers; differentiation moves cells to the surface.",[("Layers","≈ 5-30 cells"),("Turnover (skin)","≈ 28-40 days")],"The inside of your cheek replaces itself in about a week.","4.2"),
("transitional_epithelium","Transitional epithelium (urothelium)","A stretchy multi-layer lining of the bladder and ureters.","This lining can stretch when the bladder fills.","Umbrella cells flatten as the bladder expands.","Uroplakin plaques and tight junctions form a highly impermeable barrier to urine.",[("Barrier","one of the tightest in the body")],"It is among the least permeable epithelia in the body.","4.2")]:
    S2.append(N(i,t,"tissue","micro",1e-4,sm,b,d,e,f,dy,par=["epithelial_tissue"],made=["keratinocyte"] if "stratified" in i else (["enterocyte"] if "columnar" in i else []),refs=[("ANP",sec)],kn=("cell_types",)))
S2[0]["did_you_know"]="The alveolar wall that gases cross is far thinner than a human hair, about 1/100 the width."
save("body_tissues",S+S2)
